// The SAF 80C515 (Siemens/Infineon C515): MAME's mcs51 core (instruction bodies in c515_ops.inc,
// generated by tools/port_c515.py), with the 80C515's own peripherals written from c515_um.pdf:
// twelve interrupt sources in six groups at four priority levels (ch. 7), timer 2 with its reload
// (6.2.2), the A/D converter (6.4), ports 4 and 5.
#pragma once

#include <array>
#include <cstdint>

namespace virusc {

class C515 {
public:
	using u8 = uint8_t;
	using u16 = uint16_t;
	using u32 = uint32_t;
	using s8 = int8_t;

	// What the chip's pins are wired to.
	struct Bus {
		virtual ~Bus() = default;
		virtual u8 xread(u16 addr) = 0;
		virtual void xwrite(u16 addr, u8 data) = 0;
		virtual u8 portIn(int port) = 0;
		virtual void portOut(int port, u8 data) = 0;
		virtual u8 analogIn(int channel) = 0; // 0-255, the channel ADCON selects
		virtual bool rxd() = 0;               // the level on P3.0
		virtual bool rxIdle() { return false; } // P3.0 is high and stays so until a byte comes: rxd() would say so and change nothing
		virtual void txByte(u8 data) = 0;     // a byte has left TxD
	};

	void setBus(Bus *bus) { m_bus = bus; }
	// The code space: `fixed` at $0000-$7FFF, `bank` at $8000-$FFFF.
	void setCode(const u8 *fixed, const u8 *bank)
	{
		m_codeFixed = fixed;
		m_codeBank = bank;
	}
	void setCodeBank(const u8 *bank) { m_codeBank = bank; }

	void reset();
	// The level on P3.2, the external interrupt 0 pin. Edge-triggered (TCON.IT0 set), a falling edge
	// sets IE0, which vectoring clears; level-triggered, IE0 follows the pin while it is low (c515_um.pdf, ch. 7).
	void setInt0(bool level);
	// Runs at least `machineCycles` machine cycles (12 clocks each); returns how many ran.
	int run(int machineCycles);

	uint64_t cycles() const { return m_cycles; }
	u16 pc() const { return m_pc; }
	u8 sfrPeek(u8 addr) const { return m_sfrOther[addr & 0x7f]; }
	u8 tmod() const { return m_tmod; }
	u8 th1() const { return m_th1; }
	u8 pcon() const { return m_pcon; }
	u8 scon() const { return m_scon; }
	u8 adcon() const { return m_adcon; }
	u8 p(int port) const;
	u8 sp() const { return m_sp; }
	u8 iram(u8 a) const { return m_iram[a]; }

private:
	enum { PSW_CY = 7, PSW_AC = 6, PSW_FO = 5, PSW_RS = 3, PSW_OV = 2, PSW_P = 0 };
	enum { TCON_TF1 = 7, TCON_TR1 = 6, TCON_TF0 = 5, TCON_TR0 = 4, TCON_IE1 = 3, TCON_IT1 = 2, TCON_IE0 = 1, TCON_IT0 = 0 };
	enum { SCON_SM0 = 7, SCON_SM1 = 6, SCON_SM2 = 5, SCON_REN = 4, SCON_TB8 = 3, SCON_RB8 = 2, SCON_TI = 1, SCON_RI = 0 };
	enum { TMOD_GATE1 = 7, TMOD_CT1 = 6, TMOD_M1_1 = 5, TMOD_M1_0 = 4, TMOD_GATE0 = 3, TMOD_CT0 = 2, TMOD_M0_1 = 1, TMOD_M0_0 = 0 };
	enum { PCON_SMOD = 7 };
	enum { ADCON_BD = 7, ADCON_CLK = 6, ADCON_BSY = 4, ADCON_ADM = 3 };
	enum { IRCON_EXF2 = 7, IRCON_TF2 = 6, IRCON_IADC = 0 };

	static bool BIT(u32 value, int bit) { return (value >> bit) & 1; }
	u8 code(u16 a) const { return a < 0x8000 ? m_codeFixed[a] : m_codeBank[a - 0x8000]; }
	u8 iramR(u8 a) const { return m_iram[a]; }
	void iramW(u8 a, u8 d) { m_iram[a] = d; }
	u8 xdataR(u16 a) { return m_bus->xread(a); }
	void xdataW(u16 a, u8 d) { m_bus->xwrite(a, d); }
	u16 external_ram_iaddr(u16 offset, u16 mask) const { return mask == 0xff ? u16((offset & 0xff) | (m_p2 << 8)) : offset; }
	u8 sfrR(u8 a);
	void sfrW(u8 a, u8 d);
	u8 read_direct(u8 r) { return r < 0x80 ? m_iram[r] : sfrR(r); }
	void write_direct(u8 r, u8 d)
	{
		if (r < 0x80)
			m_iram[r] = d;
		else
			sfrW(r, d);
	}

	template <int bit> void set_bit(u8 &reg, bool state) { reg = u8((reg & ~(1 << bit)) | (state ? 1 << bit : 0)); }
	void set_cy(bool s) { set_bit<PSW_CY>(m_psw, s); }
	void set_ac(bool s) { set_bit<PSW_AC>(m_psw, s); }
	void set_fo(bool s) { set_bit<PSW_FO>(m_psw, s); }
	void set_rs(u8 s) { m_psw = u8((m_psw & ~(3 << PSW_RS)) | (s << PSW_RS)); }
	void set_ov(bool s) { set_bit<PSW_OV>(m_psw, s); }
	void set_p(bool s) { set_bit<PSW_P>(m_psw, s); }
	void set_tf1(bool s) { set_bit<TCON_TF1>(m_tcon, s); }
	void set_tf0(bool s) { set_bit<TCON_TF0>(m_tcon, s); }
	void set_ie1(bool s) { set_bit<TCON_IE1>(m_tcon, s); }
	void set_ie0(bool s) { set_bit<TCON_IE0>(m_tcon, s); }
	void set_rb8(bool s) { set_bit<SCON_RB8>(m_scon, s); }
	void set_ti(bool s) { set_bit<SCON_TI>(m_scon, s); }
	void set_ri(bool s) { set_bit<SCON_RI>(m_scon, s); }
	void acc_w(u8 data);

	void clear_current_irq();
	void check_irqs();
	u32 pending_irqs() const;
	void update_timer_t0(int cycles);
	void update_timer_t1(int cycles);
	void update_timer_t2();
	void update_adc();
	void transmit_receive(int source);
	void update_peripherals();
	void burn_cycles(int cycles);

	// the instruction helpers and bodies (c515_ops.inc)
	void push_pc();
	void pop_pc();
	u8 bit_address_r(u8 offset);
	void bit_address_w(u8 offset, u8 bit);
	void do_add_flags(u8 a, u8 data, u8 c);
	void do_sub_flags(u8 a, u8 data, u8 c);
	void execute_op(u8 op);
#include "c515_ops_decl_body.inc"

	static const u8 mcs51_cycles[256];
	static const u8 parity_value[256];

	Bus *m_bus = nullptr;
	const u8 *m_codeFixed = nullptr, *m_codeBank = nullptr;
	std::array<u8, 256> m_iram{};
	std::array<u8, 128> m_sfrOther{};

	u16 m_ppc = 0, m_pc = 0, m_dptr = 0;
	u8 m_rwm = 0, m_acc = 0, m_psw = 0, m_b = 0, m_sp = 7, m_pcon = 0, m_tcon = 0, m_tmod = 0, m_scon = 0, m_sbuf = 0;
	u8 m_ien0 = 0, m_ien1 = 0, m_ip0 = 0, m_ip1 = 0, m_ircon = 0, m_t2con = 0;
	bool m_int0 = true; // the level on P3.2
	u8 m_p0 = 0xff, m_p1 = 0xff, m_p2 = 0xff, m_p3 = 0xff, m_p4 = 0xff, m_p5 = 0xff;
	u8 m_tl0 = 0, m_tl1 = 0, m_th0 = 0, m_th1 = 0, m_tl2 = 0, m_th2 = 0, m_crcl = 0, m_crch = 0;
	u8 m_adcon = 0, m_addat = 0, m_dapr = 0;
	int m_adcBusy = 0; // machine cycles until the running conversion ends
	bool m_t2Prescale = false;

	int m_inst_cycles = 0, m_icount = 0;
	int m_cur_irq_prio = -1;
	u8 m_irq_active = 0;
	u32 m_irq_delayed = 0;
	u8 m_last_op = 0, m_last_bit = 0;
	uint64_t m_cycles = 0;

	struct {
		u8 data_out = 0, data_in = 0, txbit = 0, rxbit = 0, rxb8 = 0;
		int smod_div = 0, rx_clk = 0, tx_clk = 0;
	} m_uart;
};

} // namespace virusc
